INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae781164-603f-487e-a47a-444fa93e1126', '17a12797-f02b-46a3-894c-8a5a9440ca76', 0, 'Control categories — technical, managerial, operational, and physical describe WHO/WHAT implements a control and in what domain (a policy document vs. a software permission setting vs. a locked door), which is a genuinely separate classification axis from control TYPES (preventive, detective, corrective, deterrent, compensating), which describe WHEN and HOW a control acts relative to an event; the same real-world control is often classified along BOTH axes at once — e.g., a locked door is both a physical-category control and a preventive-type control.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a7b71d6-c065-45be-8583-d2d8eaf2bc9c', '17a12797-f02b-46a3-894c-8a5a9440ca76', 1, 'Control categories and control types are the exact same classification system under two different names, with no meaningful distinction between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b35e9b7d-01fe-4397-b6a1-811ffdceaa82', '17a12797-f02b-46a3-894c-8a5a9440ca76', 2, 'A single control can only ever be classified under exactly one of these two systems, never both at the same time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b026ad8-2b0c-4ce5-b1c8-77d92e172c02', '17a12797-f02b-46a3-894c-8a5a9440ca76', 3, 'This four-way classification of technical, managerial, operational, and physical controls does not exist as a recognized security concept.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc62946f-9107-4003-9013-e43d66adb74d', '1ba88717-9339-4683-bc49-d64fe3429825', 0, 'Control types — the firewall rule is PREVENTIVE (stops the event before it occurs), the SIEM alert is DETECTIVE (identifies that an event has already occurred, after the fact), and the rollback procedure is CORRECTIVE (restores normal operation after an event has caused harm); a fourth common type, deterrent, discourages an event from being attempted in the first place (e.g., a visible warning sign) rather than technically blocking or detecting it.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d0be1a16-63d6-41eb-bbb0-17d97d1b9daf', '1ba88717-9339-4683-bc49-d64fe3429825', 1, 'Control categories, since control categories are specifically defined as classifying controls by their timing relative to a security event.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc227cfe-8625-4a44-8182-4b2d1368befb', '1ba88717-9339-4683-bc49-d64fe3429825', 2, 'The CIA triad, since the CIA triad classifies controls as preventive, detective, or corrective based on timing.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db3f1455-c672-4b87-8646-b5d26f9d425a', '1ba88717-9339-4683-bc49-d64fe3429825', 3, 'All security controls act at exactly the same point in time relative to an event, making this kind of timing-based classification meaningless.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a4f77c5-9a50-4192-99bc-1cd60d3479e4', '4f50e366-0b29-4f4e-9629-d614a03ff7e3', 0, 'An insider threat — a person with legitimate, authorized access misusing that access for a malicious purpose; it is often harder to detect than an external attack specifically because the activity (accessing the customer database) looks like ordinary, authorized behavior from a legitimate credential, rather than the anomalous, unauthorized access pattern that external-attacker detection tools are typically tuned to flag.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a9a73c6-7e2f-4d64-8c35-657081d9d820', '4f50e366-0b29-4f4e-9629-d614a03ff7e3', 1, 'A zero-day vulnerability, since zero-day vulnerabilities are defined as a legitimate, authorized employee misusing their own access without any technical exploit.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48781c45-3468-4ca5-8a78-fff802cb9ff3', '4f50e366-0b29-4f4e-9629-d614a03ff7e3', 2, 'A watering hole attack, since watering hole attacks are defined as an authorized employee exporting data using their own legitimate credentials.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81deabef-538c-4da8-a711-32cdddf8208a', '4f50e366-0b29-4f4e-9629-d614a03ff7e3', 3, 'This scenario poses no real security risk, since the person involved had legitimate, authorized access to the data at the time.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dfbb2945-3c21-4110-92d0-5761383bba9b', 'cfba8579-f57c-4b97-891d-9e617e462d2f', 0, 'A supply chain attack — compromising a trusted upstream component (a software library, a vendor''s update mechanism, a hardware component during manufacturing) that many downstream organizations already depend on and trust, so that compromising ONE upstream target propagates the attacker''s access or malicious code into potentially thousands of downstream victims automatically, without directly attacking each of them individually.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cffb177b-dd0e-41a5-8a9e-cde33c26a634', 'cfba8579-f57c-4b97-891d-9e617e462d2f', 1, 'Credential stuffing, since credential stuffing is defined as compromising a widely used software library''s update mechanism to affect thousands of downstream applications.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10ef2618-21ed-42f1-a9b9-dfa1de6594fb', 'cfba8579-f57c-4b97-891d-9e617e462d2f', 2, 'A buffer overflow, since buffer overflows are defined as compromising a software maintainer''s publishing credentials to distribute a malicious update.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee815ac9-03ab-4860-bd49-ef46e34dcbc7', 'cfba8579-f57c-4b97-891d-9e617e462d2f', 3, 'This scenario is not a real, distinct attack pattern; compromising a shared upstream software dependency provides no meaningful advantage over attacking each downstream target individually.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cec2482c-ac86-4d6e-bbb3-c3fa085cf18e', 'c9bd850b-2e33-4b26-ad31-9ce4d5fe7e41', 0, 'Credential stuffing — automatically attempting known, previously-breached username/password PAIRS (from an unrelated prior breach) against a different service, relying specifically on password reuse across sites for its success, distinct from a generic brute-force attack, which instead tries many GUESSED password possibilities (often systematically, e.g., every combination or a common-password list) against a single known username, with no reliance on any specific prior data breach.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc08d62d-b4a6-42dd-bd5e-5eb548fe670b', 'c9bd850b-2e33-4b26-ad31-9ce4d5fe7e41', 1, 'A watering hole attack, since watering hole attacks are defined as attempting previously-breached username/password pairs against a different, unrelated service.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6617fb8e-eeae-4e52-9eca-c79d9548ed31', 'c9bd850b-2e33-4b26-ad31-9ce4d5fe7e41', 2, 'A supply chain attack, since supply chain attacks are defined as reusing leaked username/password pairs from an unrelated prior breach against a different service.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f143af0-f58e-4dda-909f-4315b1e6a107', 'c9bd850b-2e33-4b26-ad31-9ce4d5fe7e41', 3, 'Credential stuffing and a generic brute-force attack are identical techniques with no meaningful distinction between them.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85156e3c-9d67-4e4c-9f82-60e0c645c0ea', 'ecb18e7a-3a26-451e-b089-caf1315fd94c', 0, 'Active/active clustering — both nodes (or data centers) actively handle live production traffic simultaneously at all times, rather than one sitting idle as a passive standby; its main advantage over active/passive is that failover, if one side does fail, is faster and less disruptive (the surviving side is already actively serving traffic and simply absorbs more of it, rather than a previously-idle standby needing to be activated and warmed up from a cold or lightly-used state).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d71e041-195f-4240-8ea8-675445e993e4', 'ecb18e7a-3a26-451e-b089-caf1315fd94c', 1, 'Active/passive clustering, since active/passive clustering is specifically defined as both data centers actively handling live production traffic simultaneously.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b50836a3-2bb8-49ed-b5b3-df94cc68e1e8', 'ecb18e7a-3a26-451e-b089-caf1315fd94c', 2, 'An air-gapped network, since air-gapped networks describe two data centers actively sharing live production traffic simultaneously at all times.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ed62825-1569-48fb-a6d2-a6f2c022b4b3', 'ecb18e7a-3a26-451e-b089-caf1315fd94c', 3, 'There is no meaningful architectural difference between having both data centers actively serving traffic versus one sitting idle as a standby.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a56f536d-e5e1-40f8-b575-b82d500b957c', '552a4cee-d3a5-40c9-9138-fd934b4d27c2', 0, 'Data at rest, data in transit, and data in use — each state has a different exposure profile requiring a different protection technique: data AT REST (on disk/storage) is typically protected by encryption applied to the storage medium or file itself; data IN TRANSIT (moving across a network) is typically protected by transport-layer encryption like TLS; and data IN USE (actively being processed in memory) is the hardest to protect, since it must generally be decrypted to be usable by the processing application, requiring specialized techniques (like confidential computing / trusted execution environments) rather than the encryption approaches that work for the other two states.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b18a43c8-88e8-4d91-b3f0-bf8fde9c9aac', '552a4cee-d3a5-40c9-9138-fd934b4d27c2', 1, 'Public, Internal, and Confidential, since these are the standard terms for data at rest, data in transit, and data in use.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e62570f-2a32-4cf5-adf7-e9641f659393', '552a4cee-d3a5-40c9-9138-fd934b4d27c2', 2, 'Preventive, detective, and corrective, since these terms specifically describe the three states data can exist in (on disk, in transit, and in memory).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53d6d48d-2611-4be3-86d5-adce1e12a1c7', '552a4cee-d3a5-40c9-9138-fd934b4d27c2', 3, 'A single encryption technique protects data identically and completely across all three of these states, with no meaningful technical difference between them.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba85f7e2-d552-4aa8-9e02-441a1a84def9', 'ca3cd510-7e89-4715-9e17-9211d06d48f3', 0, 'Network-level compensating controls specifically suited to constrained/embedded devices — since the devices themselves often cannot support strong on-device security (limited compute for encryption, unpatchable firmware, weak native protocols), isolate them on a dedicated, tightly restricted network segment (connecting to network segmentation/micro-segmentation concepts covered in Paper 2), monitor their traffic closely for anomalies, and limit what they can reach — treating the NETWORK as the primary control layer specifically because the devices themselves cannot reliably provide strong security on their own.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6adc720c-eb9e-4557-b209-6b03e2385027', 'ca3cd510-7e89-4715-9e17-9211d06d48f3', 1, 'Every IoT device of this kind should always be given full, unrestricted access to the corporate network with no segmentation or restriction of any kind.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d29c0c45-8260-4420-88b3-675e153f4d71', 'ca3cd510-7e89-4715-9e17-9211d06d48f3', 2, 'Resource-constrained IoT devices always support the exact same strong on-device security capabilities as a standard enterprise server, requiring no different security approach at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e80e3e2-e5f2-426d-ba4e-4d012353a2d4', 'ca3cd510-7e89-4715-9e17-9211d06d48f3', 3, 'No security measures of any kind are possible for resource-constrained embedded/IoT devices; they must simply be left completely unprotected.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ffb72ad8-54d8-4acc-a27f-e7652fbbac2f', '3a963657-6738-4991-8e7d-f6b367b7e2ae', 0, 'Threat hunting — a proactive, hypothesis-driven search for evidence of compromise that may not have triggered any existing automated detection rule, distinct from standard SOC monitoring, which is fundamentally REACTIVE (responding to alerts already generated by existing detection tooling like a SIEM); threat hunting specifically assumes detection gaps may exist and actively looks for what automated tooling might have missed, rather than waiting for tooling to surface something on its own.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a0f42da7-c91f-429f-8c59-888c6025691b', '3a963657-6738-4991-8e7d-f6b367b7e2ae', 1, 'Vulnerability scanning, since vulnerability scanning is defined as proactively forming a hypothesis about undetected compromise and searching for supporting evidence.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3fbedfb6-442c-4243-b28e-17b20d3aa4a1', '3a963657-6738-4991-8e7d-f6b367b7e2ae', 2, 'A tabletop exercise, since tabletop exercises are defined as proactively searching system logs for evidence of undetected compromise.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e09bf13-b70e-4bdc-9e12-424612ec518a', '3a963657-6738-4991-8e7d-f6b367b7e2ae', 3, 'Threat hunting and standard alert-driven SOC monitoring are identical practices with no meaningful distinction between them.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6cbee749-8fbb-41a4-890d-46cfd62672f6', '48a9e858-eba8-4d2e-ba3d-294af3fd0906', 0, 'A write blocker — a hardware device (or software-enforced equivalent) placed between the storage media being examined and the analyst''s forensic workstation, physically or logically preventing ANY write command from reaching the original media, so the analyst can safely read from and create a forensic image of the drive with a mathematical guarantee that the original evidence remains completely unmodified throughout the process.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a98d9d2-9a01-40e3-b3eb-c52511277df9', '48a9e858-eba8-4d2e-ba3d-294af3fd0906', 1, 'A honeytoken, since honeytokens are the standard tool for physically preventing write commands from reaching a storage device during forensic examination.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3720bca6-0132-4a68-bd11-1721d7a239c9', '48a9e858-eba8-4d2e-ba3d-294af3fd0906', 2, 'A SOAR playbook, since SOAR playbooks are specifically designed to prevent write access to storage media during a forensic investigation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06151409-4ef3-474c-b4f0-e853e9df343b', '48a9e858-eba8-4d2e-ba3d-294af3fd0906', 3, 'No tool or technique can guarantee that examining a hard drive''s contents leaves the original data completely unmodified.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ad678c6-0eed-49de-aeb2-4e9effd58319', '2b1b2845-97a3-41f5-9853-f91070eadb68', 0, 'A non-credentialed scan sees only what''s visible externally (open ports, service banners, responses to network probes), typically producing a less detailed, sometimes less accurate picture, while a credentialed scan logs in and directly inspects actual installed package versions, patch levels, and configuration settings from inside the system, generally producing more accurate, more detailed findings with fewer false positives/negatives, at the cost of needing valid credentials provisioned for the scanner ahead of time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83c377ca-6502-4e76-b203-3c1221f94fba', '2b1b2845-97a3-41f5-9853-f91070eadb68', 1, 'A credentialed scan can only see externally visible information like open ports, while a non-credentialed scan directly inspects internal installed software versions and configuration settings.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c2957cb-a325-45b4-a816-ace513f007a4', '2b1b2845-97a3-41f5-9853-f91070eadb68', 2, 'Credentialed and non-credentialed scans always produce identical results with no difference in depth, detail, or accuracy.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14cce3eb-22bc-4590-aa58-8773449372ae', '2b1b2845-97a3-41f5-9853-f91070eadb68', 3, 'Vulnerability scanning can only ever be performed as a non-credentialed scan; credentialed scanning does not exist as a real technique.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0c555d6-932b-4381-8d43-77f6e1f5f198', 'd2116281-9249-4071-9f8d-057c1d6ab824', 0, 'Attack surface management — continuously discovering, inventorying, and monitoring every internet-facing and internally-reachable asset across an organization''s real environment (including previously-unknown or informally-provisioned "shadow IT" systems that never went through the normal, centrally-tracked process), specifically because a security team cannot properly assess or reduce risk on assets it doesn''t even know exist.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6de6eb0-3c23-4a31-b83d-da7ee568b7fa', 'd2116281-9249-4071-9f8d-057c1d6ab824', 1, 'A legal hold, since legal holds are the standard practice for maintaining a continuously updated inventory of internet-facing assets across an organization.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('117e97c9-77f2-498b-827d-9be4c2e922f2', 'd2116281-9249-4071-9f8d-057c1d6ab824', 2, 'Mandatory vacation, since mandatory vacation policies are specifically designed to maintain visibility into an organization''s internet-facing and internally-reachable assets.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4b1faec-75af-4aee-adac-47dca7193229', 'd2116281-9249-4071-9f8d-057c1d6ab824', 3, 'An organization''s asset inventory is always automatically complete and accurate with no ongoing effort required, including any systems provisioned outside the normal process.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('112a1633-0d72-45c4-b247-513bba0c3028', 'd73c8d30-70dd-4640-8bac-53f0b9aa10a5', 0, 'A CSIRT (Computer Security Incident Response Team) — a dedicated, cross-functional team with clearly pre-defined roles (incident commander/coordinator, technical analysts, legal, communications, and often others depending on the organization) that activates during a significant incident; defining these roles IN ADVANCE (rather than figuring it out during an active, high-pressure incident) matters because it eliminates confusion about who''s responsible for what at exactly the moment that confusion would be most costly and time-sensitive.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3f8ccfb-9e63-4313-b1ae-e17fb369445d', 'd73c8d30-70dd-4640-8bac-53f0b9aa10a5', 1, 'A honeynet, since honeynets are defined as a cross-functional team with pre-designated incident commander, technical, legal, and communications roles.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('68e31667-c5ad-478e-886e-68bc9899ab7f', 'd73c8d30-70dd-4640-8bac-53f0b9aa10a5', 2, 'An SLA (Service Level Agreement), since SLAs specifically define the incident commander, technical analyst, legal, and communications roles activated during a security incident.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7edd9be3-a70d-4327-928d-8ae820017bca', 'd73c8d30-70dd-4640-8bac-53f0b9aa10a5', 3, 'Defining incident response roles in advance provides no real benefit, since roles can always be assigned equally effectively in the middle of an active incident with no downside.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61df6d99-1e67-451d-bf4c-f14fede17c88', '2cd95d6e-1142-40a0-a7cd-519aa7475979', 0, 'A honeytoken — a single decoy piece of DATA (a fake record, credential, file, or API key) planted specifically to have no legitimate reason to ever be accessed, so that ANY access to it is a near-certain signal of unauthorized/malicious activity; this differs from a honeynet (covered in Paper 2), which is an entire decoy NETWORK/ENVIRONMENT built to attract and study attacker behavior in depth, rather than a single, narrow tripwire data point.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aab9ccef-0210-4424-86b3-ccce84e54cea', '2cd95d6e-1142-40a0-a7cd-519aa7475979', 1, 'A honeynet, since honeynets are specifically defined as a single fake database record configured to trigger an alert upon access.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('05696fc2-ef03-43cf-95e2-dd1af1280675', '2cd95d6e-1142-40a0-a7cd-519aa7475979', 2, 'A write blocker, since write blockers are the standard tool for creating fake decoy database records that trigger an alert when accessed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3062298-c075-4eca-83b8-ce1d734d7b6a', '2cd95d6e-1142-40a0-a7cd-519aa7475979', 3, 'This technique provides no real detection value, since a fake record with no legitimate purpose could never meaningfully indicate unauthorized activity.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee5a3006-3cd2-48d0-bdb8-cb01334f20fe', '8b3ced56-3daa-4d59-8ea4-184a673f1ca0', 0, 'A risk register — a living, continuously maintained record of every identified risk, tracking its likelihood, impact, assigned owner, and current treatment status (accepted, mitigated, transferred, or avoided); its ongoing governance purpose is providing leadership a single, centralized, current view of the organization''s full risk landscape, so risk-related decisions are made deliberately and with full visibility rather than piecemeal and forgotten once a risk is initially identified.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aecb7178-8896-46a1-ae87-e5879e0de415', '8b3ced56-3daa-4d59-8ea4-184a673f1ca0', 1, 'A RACI matrix, since RACI matrices are specifically defined as tracking every identified risk''s likelihood, impact, owner, and treatment status.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c9f4097-ac33-40fa-9246-df9000c0406f', '8b3ced56-3daa-4d59-8ea4-184a673f1ca0', 2, 'An AUP (Acceptable Use Policy), since AUPs are the standard document for tracking organizational risk likelihood, impact, ownership, and treatment status.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1d9467f-bb75-468f-bc95-c85e659cb108', '8b3ced56-3daa-4d59-8ea4-184a673f1ca0', 3, 'Once a risk is initially identified and documented one time, no ongoing tracking or maintenance of that record is necessary or useful.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f8eaa3f-f2da-4a42-bd03-960a2c9bd3a3', '530b87f0-257a-43c8-93fa-9f46ba602fc9', 0, 'A Data Protection Officer (DPO) — a formally designated individual responsible for overseeing an organization''s data protection compliance, serving as a point of contact for data protection regulators and for individuals exercising their data rights, and advising on privacy considerations for new projects or data-processing activities; certain organizations processing personal data at scale (particularly under GDPR) are specifically required to designate one.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9bff423-95c0-4f90-b929-71cacc646f72', '530b87f0-257a-43c8-93fa-9f46ba602fc9', 1, 'A bastion host, since a bastion host is specifically defined as a designated individual overseeing an organization''s data protection compliance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6fb60e1c-4fda-4ebb-b153-2a586265852a', '530b87f0-257a-43c8-93fa-9f46ba602fc9', 2, 'A CSIRT, since a CSIRT is specifically the individual role responsible for ongoing data protection compliance oversight and serving as the regulator point of contact.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('121bf076-e014-49d8-9b9c-5ee62a067172', '530b87f0-257a-43c8-93fa-9f46ba602fc9', 3, 'No formal, named governance role exists anywhere for overseeing an organization''s data protection compliance on an ongoing basis.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0251027-30ab-4fc7-afb1-43819210a3fa', '41ac958c-cdca-4ba7-8547-7ac4d9b08820', 0, 'A security framework/standard — a structured, widely recognized set of best-practice categories and guidance (like NIST CSF or ISO 27001) that an organization can voluntarily adopt to organize its security program and communicate its maturity in a common, recognizable structure; this differs from a specific regulation (like HIPAA, covered in Paper 1, or GDPR, covered in Paper 4) in that a framework is generally not itself a legally-binding requirement (though it can be REFERENCED or effectively required within a specific contract, industry certification, or regulation), while a regulation carries direct legal force and specific penalties for non-compliance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc22a592-32a6-4807-9870-12d42fdace71', '41ac958c-cdca-4ba7-8547-7ac4d9b08820', 1, 'A risk register, since risk registers are specifically defined as a widely recognized structure like NIST CSF or ISO 27001 for organizing security best practices.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd29b3ce-02f9-4a3e-859d-82373b13a0c8', '41ac958c-cdca-4ba7-8547-7ac4d9b08820', 2, 'An attack surface management program, since attack surface management is specifically defined as adopting a recognized security framework like NIST CSF or ISO 27001.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce4aef6d-5418-4755-9d44-796a29b84092', '41ac958c-cdca-4ba7-8547-7ac4d9b08820', 3, 'A security framework and a specific legal regulation are functionally and legally identical in every respect, with no meaningful distinction between them.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4e35074-773d-495a-88a4-00189c92253e', '4da24a4a-150b-48cf-8f84-bb231c74d327', 0, 'Risk appetite (or risk tolerance) — a general, organization-wide statement of how much risk a company is willing to accept in pursuit of its objectives, set at a governance/board level BEFORE any specific individual risk is evaluated; this differs from risk acceptance (covered in Paper 1), which is a decision made about one SPECIFIC, already-identified risk, ideally guided by the organization''s previously-established risk appetite rather than decided independently and inconsistently case by case.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8cd06b5d-c833-4711-a8ce-3c32844fba12', '4da24a4a-150b-48cf-8f84-bb231c74d327', 1, 'A honeytoken, since honeytokens are specifically defined as a board-level, organization-wide policy statement about acceptable risk tolerance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf54c89a-459e-4407-accf-90970539bd8e', '4da24a4a-150b-48cf-8f84-bb231c74d327', 2, 'Risk acceptance, since risk acceptance and this general, organization-wide policy statement are the exact same concept with no meaningful distinction.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26a26d7e-f0dd-4c19-bce7-027864ccd5f5', '4da24a4a-150b-48cf-8f84-bb231c74d327', 3, 'Organizations never make general, advance statements about their overall risk tolerance; every risk decision is always made in complete isolation with no consistent guiding principle.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bbd94bac-31b9-4fe9-8e20-b5647a456848', '43bff02a-ce5b-4fb4-9324-e4030ed4d1f9', 0, 'A buffer overflow — occurs when a program writes more data into a fixed-size memory buffer than that buffer was actually allocated to hold, and without proper bounds checking, that excess data overwrites adjacent memory; at minimum this typically crashes the program (a denial-of-service effect), but if the attacker carefully controls what gets written into the overwritten memory, it can potentially lead to arbitrary code execution, making this a genuinely severe, foundational memory-safety vulnerability class.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d18369dd-ced1-4748-9ae5-8b635c648a5f', '43bff02a-ce5b-4fb4-9324-e4030ed4d1f9', 1, 'Credential stuffing, since credential stuffing is defined as writing more data into a fixed-size memory buffer than it was allocated to hold.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc3c57ee-1981-4541-b521-457438c14214', '43bff02a-ce5b-4fb4-9324-e4030ed4d1f9', 2, 'A supply chain attack, since supply chain attacks are defined as overwriting adjacent memory by submitting input longer than an allocated buffer.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f487f074-77f6-4098-86e5-b717fd371830', '43bff02a-ce5b-4fb4-9324-e4030ed4d1f9', 3, 'This scenario cannot actually cause a program to crash or behave unexpectedly, since input length has no real effect on memory allocated for it.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a6fd2235-b838-4a49-9dcb-161ea4350e4b', '075424c1-9157-48f8-8032-2992a048afe7', 0, 'API security — addressed through API keys or OAuth tokens for authenticating each calling application, rate limiting (often enforced at an API gateway) to prevent any single caller from overwhelming the API with excessive volume, and fine-grained authorization scoping so each authenticated caller can only access the specific data/operations it''s actually been granted, rather than broad, undifferentiated access to the entire API surface once any valid credential is presented.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0589fcc6-8f35-4eb8-8402-bd655da9c3c6', '075424c1-9157-48f8-8032-2992a048afe7', 1, 'An air-gapped network, since air-gapped networks are the standard mechanism for authenticating external partner applications and rate-limiting their API request volume.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f751212-65f9-4db9-ba69-51cea64e9dc7', '075424c1-9157-48f8-8032-2992a048afe7', 2, 'A honeytoken, since honeytokens are specifically used to authenticate calling applications and enforce per-application rate limits on a REST API.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e6f5ddc-9b89-481c-9eec-60180523d161', '075424c1-9157-48f8-8032-2992a048afe7', 3, 'Once a REST API is deployed, no further authentication, rate limiting, or access scoping is possible or necessary for any calling application.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
